sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var updates = [];

    // 1. Check State
    if (current.state.changes()) {
        updates.push("- Estado: '" + previous.state.getDisplayValue() + "' a '" + current.state.getDisplayValue() + "'");
    }

    // 2. Check Valor Estimado
    if (current.valor_estimado.changes()) {
        updates.push("- Valor Estimado: " + previous.valor_estimado + " a " + current.valor_estimado);
    }

    // 3. Check Unidad Orgánica
    if (current.company.changes()) {
        updates.push("- Unidad Orgánica: " + previous.company.getDisplayValue() + " a " + current.company.getDisplayValue());
    }

    // 4. Check Tipo de contrato
    if (current.tipo_de_contrato.changes()) {
        updates.push("- Tipo de contrato: " + previous.tipo_de_contrato.getDisplayValue() + " a " + current.tipo_de_contrato.getDisplayValue());
    }

    //5. Check Fecha licitación
    if (current.fecha_licitacion.changes()) {
        updates.push("- Fecha licitación: " + previous.fecha_licitacion.getDisplayValue()  + " a " +  current.fecha_licitacion.getDisplayValue());
    }
	if (current.short_description.changes()) {
        updates.push("- Denominación del contrato/acuerdo marco: " + previous.short_description.getDisplayValue()  + " a " +  current.short_description.getDisplayValue());
    }

    // If any changes were detected, post them as a single comment
    if (updates.length > 0) {
        current.comments = "Actualizaciónes:\n" + updates.join("\n");
    }
})(current, previous);
